 [665]=function()
 PlayBGM(11);
talk(1,"乿乿, 僝媤丟唝侰! 丟乨 刾乛 媅僑 剏媬乛 乶丩妋!",
 9,"乿侾丏 俽匵働丏 俍俒 厈僼僲丩 丠俠 刲刴 俍俲唝侰. 妎丮, 僟乛 丒俋丅 侹匵.",
 9,"俷·噞·乕 僶 僾俧俠 乪凾乛 唚嘵乤僤 凘丟 嘕侾怬丅 僕凷俬 員乨乷丮. 丟 丆倈乛 丟係侰丄 僾俠 俿乤俬 剋匢乆 乹 俛丮. 乤乥 匞僢 刦乤僄凷 丳丮.",
 1,"匞僢 刦丳丮僤?",
 9,"僛奞丮. 僟乛 匞僲丄 亅亇働 圧圗丟 峑侰乽俧 僺僼丮. 丟係 丂哯丼 廞剘僲丩, 塹協 乪僌俬 匞丟僤 僛 倁丷丼 俵乕乫 媂剕剗 乕噝 噞丟 丮別丵 乤僠 乷 僽丟丮.");
talk(126,"両嘕丟! 僛奞丮丄 乕噝 噞働 丮弙丟 乿乿働 廠丟刱哅 坾乯乛.",
 9,"僛奞丮. 僛刄 僾俠 丟唚 俛俠 坲丟丩 俵乕丏 匵侻 媈僤 噞亄 塲匸 乹 凮刱侰. 僛乽 乥婬丮刅 噞亄 乕乛 俵哶乆 剓僢 寋刧丮. 侴侾, 刾乛 俵乕俬 刼媉乆 剓僢 唦僲凷 僝媤丟刱丮.",
 1,"……",
 9,"噞亄 乕乛 塇奯 丆乤丄 係唖 婮丟 坥乤坋 単僢 婮丏 僎僄乛 刕丵 刜乯丮. 僛刄 僾僕丄 嘫嘆丵 丟僄僤 俷乛 俿乤俬 剋匢乷丮. 僛僽丟 僟 凾刐丟刱丮刅…… 僟乛 孏剘倃僾.",
 9,"丵丮乛 僾俧俬 乿侾 俰俷乫丵 奅孖 僽丏 僴 奤坒丟刱丮. 丟 僾俧乛 僛厁働 嘫乫 丟塖卨 媇丟 両丠僃僲丩. 丟 乶奒丮嘢 儃匵協 丟 孊丟 凜刱倃僾.",
 1,"……",
 9,"噈僾 丟俖凷 媅僾侰俠 俴俠丮! 丠俬 刜僤 俷噝 噞丼 乄奝 俿乤俬 剋匢乤唝丮. 侴侾, 僟 媎丼 乛凷噁侰 匵俧.",
 1,"乿乿, 僛婡 乣侲丟 僶丆乫 侭俤丼 刅僐刱僤 刅唀儃丼 丏刣乫 僂刔僯 僎弐丟乕! 俵卆, 乥哸, 僎乵, 僎僅…… 俍俒 乨 墈厈刅 嶫孖 厁僐丟乕. 乿乿, 僛俖 嘜乷 僛僐亄 丮俲侰 俴乵.",
 9,"両嘕丟! 僾俬 俵卆 俰俷噝 凣丮僤! 僤嘋乷 僽……!",
 1,"乿乿, 俿乤乛 丟唚 僛俖俬 刼媉乤侰 俴乵! 僾俧俬 係侰妏奧僤 丷僩丼 丅嘡僲丩 匞侰 俴僤僕俠 俿乤乫 俽巄乆 唕丟 俛乵.");
